/* @lc app=leetcode id=3796 lang=kotlin */ class Solution { fun findMaxVal(n: Int, restrictions: Array<IntArray>, diff: IntArray): Int = LongArray(n) { if (it == 0) 0L else Long.MAX_VALUE / 4 }.also { r -> restrictions.forEach { (i, v) -> r[i] = minOf(r[i], v.toLong()) } }.also { r -> (1 until n).forEach { i -> r[i] = minOf(r[i], r[i - 1] + diff[i - 1]) } }.also { r -> (n - 2 downTo 0).forEach { i -> r[i] = minOf(r[i], r[i + 1] + diff[i]) } }.max().toInt() }